#!/bin/bash
# Identifies a copy of NFS Most Wanted (Xbox 360) on the console, for this port.
# Generated by batocera/tools/gen_identifier.py: edit that file, not this one.
#
# As a Port: copy it to /userdata/roms/ports/ and launch it, or over SSH:  bash "Identifier NFSMW.sh" [folder]
# It finds every default.xex under /userdata and /media (or takes the folder given), hashes the files and writes
# /userdata/roms/ports/nfsmw-identification.txt. About a minute or two per copy (~7 GB). Nothing is changed.
HERE="$(cd "$(dirname "$0")" && pwd)"
OUT="$HERE/nfsmw-identification.txt"
exec > "$OUT" 2>&1
echo "== NFSMW identification $(date '+%F %T')"

# default.xex of every known edition (tools/editions/regional/ediciones.json)
EDITIONS='aad15fc218d034de3131f746e0b763dd8049a40dd676efc87667fcaf4fc72694 pal_es PAL España
aebdf3c14d1e4e4ed2c130d94bc1a0e97bd6d5bf39bdfdef33c3909c9cc4ba4c usa USA
23af89d49a713ff948af7b9bc06557b06e94e8629adc40a29513ab6f5cafb33d jpn Japón
23ece29d18724ea28971d52f936964d127148bd2359ff24795da7442b9069bf4 pal_de PAL Alemania
acb09332bcafc15e8e21dc15062f1963804a3176fa4db48fea7f6c8afbdff066 pal_it PAL Italia
229c5ed5dcc67871982000fb923acfd59494f21f30996b25f36b30a8d85c9b7b pal_fr PAL Francia
e2ea2ff11bf84cb30430d824d7bfe699a3acf3e7400d21b9a7c938e3d7a10474 pal_en PAL Reino Unido
a2dd0156c26603cf32e33b52fa906422bde74e5065da87115d5b747aa5d90ff8 pal_pl PAL Polonia (fans)
47683b515e5461a2e356c45a4417f30fe69c3f6c6ea0d3352829f35f1fb33abe kor Corea
0cd7b9fa3957de085e298c91faa726116ad0079abaefead82c2f3337ee432e64 cht Asia (chino tradicional)'

report() {
  local DIR="$1" xex ed f
  echo
  echo "################ $DIR"
  xex=$(sha256sum "$DIR/default.xex" | cut -d' ' -f1)
  echo "default.xex sha256: $xex  size: $(stat -c %s "$DIR/default.xex")"
  ed=$(echo "$EDITIONS" | grep "^$xex " | cut -d' ' -f2-)
  echo "edition: ${ed:-UNKNOWN (modified or unlisted executable)}"
  # nfsmw-nx tools/french-dub (PAL English -> French): ZDIR.BIN points ENGLISH.BIN at FRENCH.BIN, new ZZDATA9.
  # Batocera layout: default.xex may sit next to the executable while the disc files are in game_root/.
  local DATA="$DIR"
  [ ! -d "$DIR/NFS" ] && [ -d "$DIR/game_root/NFS" ] && DATA="$DIR/game_root" && echo "(disc files in game_root/)"
  [ -f "$DATA/NFS/ZDIR.BIN" ] && echo "NFS/ZDIR.BIN sha256: $(sha256sum "$DATA/NFS/ZDIR.BIN" | cut -d' ' -f1)"
  for f in Movies/movies_report.txt Movies/rapport_films.txt; do
    [ -f "$DATA/$f" ] && echo "nfsmw-nx French dub marker: $f"
  done
  ls "$DATA"/Movies/*french* >/dev/null 2>&1 && echo "Movies: French-named files present"
  [ -f "$DATA/nfsmw_shaders.nfsp" ] || [ -f "$DIR/nfsmw_shaders.nfsp" ] && echo "nfsmw_shaders.nfsp: present"
  echo "-- files (size path)"
  (cd "$DATA" && find . -type f | sed 's|^\./||' | sort | while read -r f; do echo "$(stat -c %s "$f") $f"; done)
}

# The folder given, else every default.xex under /userdata (roms, ports, USB/SD mounts under /media too).
if [ -n "${1:-}" ]; then
  DIRS="$1"
else
  DIRS=$(find /userdata /media "$HERE" -maxdepth 7 -type f -iname default.xex 2>/dev/null | while read -r f; do dirname "$f"; done | sort -u)
fi
if [ -z "$DIRS" ]; then
  echo "no default.xex found under /userdata or /media."
  echo "Copy the extracted game (default.xex, NFS/, Movies/) to /userdata/roms/ports/NFS Most Wanted.sh/game_root/ and run again."
  echo "ISO images found (not opened):"
  find /userdata /media -maxdepth 7 -type f -iname '*.iso' -size +1G 2>/dev/null | while read -r f; do echo "  $(stat -c %s "$f") $f"; done
  exit 1
fi
while read -r d; do [ -n "$d" ] && report "$d"; done <<< "$DIRS"
echo
echo "== done"
